import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o as a,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const k=JSON.parse('{"title":"Grok Business & Enterprise","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/grok/grok-business.md","filePath":"products/ai-coding/grok/grok-business.md","lastUpdated":1787110548000}'),s={name:"products/ai-coding/grok/grok-business.md"};function n(i,e,l,d,c,g){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="grok-business-enterprise" tabindex="-1">Grok Business &amp; Enterprise <a class="header-anchor" href="#grok-business-enterprise" aria-label="Permalink to &quot;Grok Business &amp; Enterprise&quot;">​</a></h1><blockquote><p>Official positioning (<a href="https://docs.x.ai/grok/user-guide" target="_blank" rel="noreferrer">docs.x.ai/grok/user-guide</a>): &quot;<strong>Grok Business provides dedicated workspaces for personal and team use, with enhanced privacy and sharing controls.</strong>&quot;</p><p><a href="https://docs.x.ai/grok/overview" target="_blank" rel="noreferrer">docs.x.ai/grok/overview</a> lists <strong>Business &amp; Enterprise</strong> as a first-class next step: &quot;team workspaces, licenses, and organization controls.&quot;</p><p>This page is a product map for that official entry. On this site&#39;s complexity axis it sits later than Grok Build. It still gets a page because xAI put it on the Grok docs home.</p></blockquote><h2 id="goals-and-non-goals" tabindex="-1">Goals and non-goals <a class="header-anchor" href="#goals-and-non-goals" aria-label="Permalink to &quot;Goals and non-goals&quot;">​</a></h2><p><strong>Audience:</strong> someone whose company already has (or is buying) Grok Business / Enterprise, not a solo SuperGrok subscriber.</p><p><strong>Goals:</strong> explain personal vs team workspaces, licenses, sharing, and the admin console. Point at official pages.</p><p><strong>Non-goals:</strong> invented seat prices, a second copy of Enterprise legal terms, or Grok Build&#39;s <code>/etc/grok/requirements.toml</code> policy (that is <a href="https://docs.x.ai/build/enterprise" target="_blank" rel="noreferrer">enterprise CLI policy</a>, a different product).</p><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><p>A <strong>team workspace</strong> (<a href="https://docs.x.ai/grok/user-guide" target="_blank" rel="noreferrer">user-guide</a>):</p><ul><li>Privacy guarantees as outlined in xAI&#39;s <a href="https://x.ai/legal/terms-of-service-enterprise" target="_blank" rel="noreferrer">enterprise terms</a>.</li><li>Full benefits of <strong>SuperGrok</strong> (or <strong>SuperGrok Heavy</strong> for upgraded licenses).</li><li>Secure sharing of conversations limited to <strong>active</strong> team members.</li></ul><p>Two workspace types:</p><table tabindex="0"><thead><tr><th>Workspace</th><th>Who it is for</th><th>Gate</th></tr></thead><tbody><tr><td><strong>Personal</strong></td><td>Individual use</td><td>Available unless the org disables it on an Enterprise license</td></tr><tr><td><strong>Team</strong></td><td>Collaborative work</td><td>Only with an <strong>active license</strong></td></tr></tbody></table><p>Switch workspaces with the selector in the <strong>bottom-left</strong> navigation on grok.com. Start new conversations in the correct workspace.</p><p>If you cannot open the team workspace, you lack an active license — contact a team admin. If you <strong>do not see a personal workspace</strong>, the org disabled it; enabling/disabling that is an Enterprise / sales conversation (<a href="https://docs.x.ai/grok/user-guide" target="_blank" rel="noreferrer">user-guide</a>).</p><p>Enterprise adds custom retention policies. This page does not paraphrase the legal terms — read <a href="https://x.ai/legal/terms-of-service-enterprise" target="_blank" rel="noreferrer">x.ai/legal/terms-of-service-enterprise</a>.</p><h2 id="licenses-and-users" tabindex="-1">Licenses and users <a class="header-anchor" href="#licenses-and-users" aria-label="Permalink to &quot;Licenses and users&quot;">​</a></h2><p>Hub: the Grok Business overview at <a href="https://console.x.ai" target="_blank" rel="noreferrer">console.x.ai</a> (<a href="https://docs.x.ai/grok/management" target="_blank" rel="noreferrer">management</a>, <a href="https://docs.x.ai/grok/user-guide" target="_blank" rel="noreferrer">user-guide</a>).</p><p>Official license types (<a href="https://docs.x.ai/grok/management" target="_blank" rel="noreferrer">management</a>):</p><ul><li><strong>SuperGrok</strong> — standard business access with enhanced quotas and features.</li><li><strong>SuperGrok Heavy</strong> — upgraded performance for demanding workloads.</li></ul><p>This page does <strong>not</strong> invent a dollar price per seat.</p><p>Admin flow (condensed from <a href="https://docs.x.ai/grok/management" target="_blank" rel="noreferrer">management</a> and <a href="https://docs.x.ai/grok/user-guide" target="_blank" rel="noreferrer">user-guide</a>):</p><ol><li>Buy licenses on the overview (type + quantity). Needs <strong>Billing Read-Write</strong>.</li><li>Invite users by email; optionally pick a license to auto-provision on accept. Needs <strong>Team Read-Write</strong>. Invited users get team workspace access and basic team read (so conversations can be shared).</li><li>Assign / revoke licenses from the user list. Revoke returns the license to the pool and drops <strong>team</strong> workspace access; <strong>personal</strong> workspace remains.</li><li>Cancel unused licenses on the overview. Cancellations may take a few days; eligible refunds go to the billing method.</li></ol><p>End-user activation (<a href="https://docs.x.ai/grok/user-guide" target="_blank" rel="noreferrer">user-guide</a>): console.x.ai → <strong>Assign license</strong> → pick the type. Then the team workspace appears on grok.com.</p><h2 id="sharing" tabindex="-1">Sharing <a class="header-anchor" href="#sharing" aria-label="Permalink to &quot;Sharing&quot;">​</a></h2><p>Team conversation sharing (<a href="https://docs.x.ai/grok/user-guide" target="_blank" rel="noreferrer">user-guide</a>):</p><ol><li>Open the conversation <strong>in the team workspace</strong>.</li><li>Share button → select team members → generate the link.</li><li>Links open only for <strong>licensed</strong> team members. Non-members and unlicensed teammates cannot open them.</li><li>Inbox: <a href="https://grok.com/history?tab=shared-with-me" target="_blank" rel="noreferrer">grok.com/history?tab=shared-with-me</a>.</li></ol><p>Org-wide sharing policy is a <strong>ceiling</strong>, not a default share (<a href="https://docs.x.ai/grok/management" target="_blank" rel="noreferrer">management</a>). Admins set it in console.x.ai → <strong>Sharing &amp; Retention</strong> → <strong>Product Sharing</strong>. Each resource type has its own policy: conversations, projects, skills.</p><table tabindex="0"><thead><tr><th>Level</th><th>What members can do</th></tr></thead><tbody><tr><td><strong>Private</strong></td><td>Sharing off for that resource</td></tr><tr><td><strong>Team</strong></td><td>Individual teammates and the member&#39;s own team. No org-wide / cross-team</td></tr><tr><td><strong>Organization</strong></td><td>Team, plus other teams and everyone in the org</td></tr><tr><td><strong>Public</strong></td><td>Organization, plus public links anyone can open</td></tr></tbody></table><p>Public links apply to <strong>conversations only</strong>. Projects and skills cap at Organization. Defaults: conversations and projects can be shared organization-wide; <strong>skills start at Private</strong>. Tightening a policy applies immediately, including existing shares that now sit above the ceiling.</p><h2 id="connectors-in-a-team" tabindex="-1">Connectors in a team <a class="header-anchor" href="#connectors-in-a-team" aria-label="Permalink to &quot;Connectors in a team&quot;">​</a></h2><p>Business / Enterprise members do <strong>not</strong> add connectors on their own first. A team admin must provision the connector in the console; then members connect their own accounts on <a href="https://grok.com/connectors" target="_blank" rel="noreferrer">grok.com/connectors</a>. Details: <a href="./grok-connectors.html">Connectors</a> and <a href="https://docs.x.ai/grok/connector-management" target="_blank" rel="noreferrer">connector-management</a>.</p><h2 id="not-this-page" tabindex="-1">Not this page <a class="header-anchor" href="#not-this-page" aria-label="Permalink to &quot;Not this page&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Product</th><th>Why it is different</th></tr></thead><tbody><tr><td>Personal SuperGrok on grok.com</td><td>No team workspace, no license pool. See <a href="./grok-chat.html">Grok Chat</a></td></tr><tr><td>xAI API &quot;teams&quot; in the consumer <a href="https://docs.x.ai/grok/faq" target="_blank" rel="noreferrer">FAQ</a></td><td>Console teams for <strong>API usage / invoices</strong>, not Grok Business workspaces</td></tr><tr><td>Grok Build enterprise policy</td><td>Five config layers, OIDC, MDM on the <strong>CLI</strong> (<a href="https://docs.x.ai/build/enterprise" target="_blank" rel="noreferrer">docs.x.ai/build/enterprise</a>)</td></tr><tr><td>Grok Bot teams</td><td>Per-member cloud computer (<a href="https://docs.x.ai/grok-bot/teams-and-enterprises" target="_blank" rel="noreferrer">docs.x.ai/grok-bot/teams-and-enterprises</a>)</td></tr></tbody></table><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li>Starting a confidential thread in the <strong>personal</strong> workspace, then wondering why team sharing links do not work.</li><li>Expecting an unlicensed teammate to open a share link. Officially they cannot.</li><li>Mixing Grok Business licenses with <code>XAI_API_KEY</code> API credit.</li><li>Looking for a seat price on this page. Official docs list <strong>license types</strong>, not consumer dollar amounts.</li></ul><h2 id="official-docs" tabindex="-1">Official docs <a class="header-anchor" href="#official-docs" aria-label="Permalink to &quot;Official docs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Use</th></tr></thead><tbody><tr><td><a href="https://docs.x.ai/grok/user-guide" target="_blank" rel="noreferrer">docs.x.ai/grok/user-guide</a></td><td>Workspaces, privacy, conversation sharing, activate license</td></tr><tr><td><a href="https://docs.x.ai/grok/management" target="_blank" rel="noreferrer">docs.x.ai/grok/management</a></td><td>Buy / invite / assign / revoke / cancel, sharing policy</td></tr><tr><td><a href="https://docs.x.ai/grok/connector-management" target="_blank" rel="noreferrer">docs.x.ai/grok/connector-management</a></td><td>Admin provisions connectors</td></tr><tr><td><a href="https://docs.x.ai/grok/overview" target="_blank" rel="noreferrer">docs.x.ai/grok/overview</a></td><td>First-class &quot;Business &amp; Enterprise&quot; link</td></tr><tr><td><a href="https://console.x.ai" target="_blank" rel="noreferrer">console.x.ai</a></td><td>Admin hub</td></tr><tr><td><a href="https://x.ai/legal/terms-of-service-enterprise" target="_blank" rel="noreferrer">enterprise terms</a></td><td>Privacy / data handling</td></tr></tbody></table><p>White-glove / Enterprise upgrades: contact xAI sales (the docs pages leave the address as a site widget).</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./grok-chat.html">Grok Chat</a> — what members use inside a workspace</li><li><a href="./grok-connectors.html">Connectors</a> — admin provision + member OAuth</li><li><a href="./grok-bot.html">Grok Bot</a> — different team product</li><li><a href="./grok-cli.html">Grok Build tutorial</a> — CLI enterprise policy is elsewhere</li><li><a href="./">Grok learning map</a></li></ul>',39)])])}const f=t(s,[["render",n]]);export{k as __pageData,f as default};
